// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SelfHostedNode) predicate.SelfHostedNode {
	return predicate.SelfHostedNode(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SelfHostedNode) predicate.SelfHostedNode {
	return predicate.SelfHostedNode(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SelfHostedNode) predicate.SelfHostedNode {
	return predicate.SelfHostedNode(sql.NotPredicates(p))
}
